public int calculateMinimumTourLength(int N, int[] X) {
    int totalLength = 0;
    for (int i = 0; i < N; i++) {
        totalLength += Math.abs(X[i] - X[(i + 1) % N]);
    }

    int minTourLength = Integer.MAX_VALUE;
    for (int i = 0; i < N; i++) {
        int closedBridgeLength = Math.abs(X[i] - X[(i + 1) % N]);
        int newTourLength = totalLength - closedBridgeLength;
        minTourLength = Math.min(minTourLength, newTourLength);
    }

    return minTourLength;
}

